// How applications from this template are underwritten.
type UnderwritingMode string

const (
	UnderwritingModeAutomatic UnderwritingMode = "automatic"
	UnderwritingModeManual    UnderwritingMode = "manual"
	UnderwritingModeBypass    UnderwritingMode = "bypass"
)

func NewUnderwritingModeFromString(s string) (UnderwritingMode, error) {
	switch s {
	case "automatic":
		return UnderwritingModeAutomatic, nil
	case "manual":
		return UnderwritingModeManual, nil
	case "bypass":
		return UnderwritingModeBypass, nil
	}
	var t UnderwritingMode
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (u UnderwritingMode) Ptr() *UnderwritingMode {
	return &u
}
